from math import gcd

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def primitive_part(n):
    r = fib(n)
    for d in (d for d in range(1, n) if n % d == 0):
        fd = fib(d)
        g = gcd(r, fd)
        while g > 1:
            r //= g
            g = gcd(r, fd)
    return r

for n in [1, 2, 6, 12]:
    print(f'F_{n} = {fib(n)}, primitive part = {primitive_part(n)} (no primitive divisor)')
for n in range(13, 22):
    pp = primitive_part(n)
    print(f'F_{n} = {fib(n)}, primitive part = {pp} > 1  -> primitive divisor exists')

