function RANK(perm[0..n-1]):
    for i in 0 .. n-1:
        lehmer[i] <- #{ j > i : perm[j] < perm[i] }
    code <- reverse(lehmer)     // digit at place j! is <= j
    return sum over i of code[i] * i!

function UNRANK(r, n):
    for i in 0 .. n-1: code[i] <- (r // i!) mod (i+1)
    lehmer <- reverse(code)
    avail <- [0, 1, ..., n-1]
    for c in lehmer: output avail.pop(c)

function PRIMITIVE_PART(n):
    r <- F(n)
    for each d dividing n with 0 < d < n:
        fd <- F(d)
        while gcd(r, fd) > 1:
            r <- r / gcd(r, fd)
    return r      // pi(n)

function PRIMITIVE_DIVISOR(n):
    pp <- PRIMITIVE_PART(n)
    if pp <= 1: return NONE       // only n in {1,2,6,12}
    return smallest prime factor of pp

