import matplotlib.pyplot as plt

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_prime(m):
    if m < 2:
        return False
    i = 2
    while i * i <= m:
        if m % i == 0:
            return False
        i += 1
    return True

primes = [p for p in range(2, 500) if is_prime(p)]
entry = {}
for n in range(1, 60):
    fn = fib(n)
    for p in primes:
        if p not in entry and fn % p == 0:
            entry[p] = n
xs = sorted(entry)
ys = [entry[p] for p in xs]
plt.figure(figsize=(9, 5))
plt.scatter(xs, ys, s=18)
plt.xlabel('prime p')
plt.ylabel('entry point: least n with p | F_n')
plt.title('Fibonacci entry points of primes')
plt.grid(True, alpha=0.3)
